def SKRStartOCCULTATIONSVector(builder, numElems):
    return builder.StartVector(32, numElems, 8)

def StartOCCULTATIONSVector(builder, numElems):
    return SKRStartOCCULTATIONSVector(builder, numElems)

def SKRCreateOCCULTATIONSVector(builder, data):
    data = list(data)
    builder.StartVector(32, len(data), 8)
    for item in reversed(data):
        item.Pack(builder)
    return builder.EndVector()

def CreateOCCULTATIONSVector(builder, data):
    SKRCreateOCCULTATIONSVector(builder, data)

def SKRAddEXCLUSIONS(builder, EXCLUSIONS):
    builder.PrependUOffsetTRelativeSlot(24, flatbuffers.number_types.UOffsetTFlags.py_type(EXCLUSIONS), 0)

def AddEXCLUSIONS(builder, EXCLUSIONS):
    SKRAddEXCLUSIONS(builder, EXCLUSIONS)

def SKRStartEXCLUSIONSVector(builder, numElems):
    return builder.StartVector(32, numElems, 8)

def StartEXCLUSIONSVector(builder, numElems):
    return SKRStartEXCLUSIONSVector(builder, numElems)

def SKRCreateEXCLUSIONSVector(builder, data):
    data = list(data)
    builder.StartVector(32, len(data), 8)
    for item in reversed(data):
        item.Pack(builder)
    return builder.EndVector()

def CreateEXCLUSIONSVector(builder, data):
    SKRCreateEXCLUSIONSVector(builder, data)

def SKREnd(builder):
    return builder.EndObject()

def End(builder):
    return SKREnd(builder)

import SKRExclusion
import SKRHit
import SKROccultation
try:
    from typing import List
except:
    pass

class SKRT(object):

    # SKRT
    def __init__(
        self,
        QUERY_ID = None,
        QUERY_KIND = 0,
        STATUS = 0,
        MESSAGE = None,
        EPOCH_JD_TT = float('nan'),
        EPOCH_JD_TT_FRACTION = 0.0,
        PLACE = 3,
        ROW_COUNT = 0,
        ROWS_ADDED = 0,
        REJECTED_COUNT = 0,
        BAND_COUNT = 0,
        MATCHED_COUNT = 0,
        HITS = None,
        BAND_IDS = None,
        MAGNITUDES = None,
        DERIVATIONS = None,
        MATCHED_DETECTIONS = 0,
        ROTATION = None,
        QUATERNION = None,
        RESIDUAL_RMS_ARCSEC = float('nan'),
        BORESIGHT_RA_DEG = float('nan'),
        BORESIGHT_DEC_DEG = float('nan'),
        MATCHED_ROWS = None,
        OCCULTATIONS = None,
        EXCLUSIONS = None,
    ):
        self.QUERY_ID = QUERY_ID  # type: Optional[str]
        self.QUERY_KIND = QUERY_KIND  # type: int
        self.STATUS = STATUS  # type: int
        self.MESSAGE = MESSAGE  # type: Optional[str]
        self.EPOCH_JD_TT = EPOCH_JD_TT  # type: float
        self.EPOCH_JD_TT_FRACTION = EPOCH_JD_TT_FRACTION  # type: float
        self.PLACE = PLACE  # type: int
        self.ROW_COUNT = ROW_COUNT  # type: int
        self.ROWS_ADDED = ROWS_ADDED  # type: int
        self.REJECTED_COUNT = REJECTED_COUNT  # type: int
        self.BAND_COUNT = BAND_COUNT  # type: int
        self.MATCHED_COUNT = MATCHED_COUNT  # type: int
        self.HITS = HITS  # type: Optional[List[SKRHit.SKRHitT]]
        self.BAND_IDS = BAND_IDS  # type: Optional[List[Optional[str]]]
        self.MAGNITUDES = MAGNITUDES  # type: Optional[List[float]]
        self.DERIVATIONS = DERIVATIONS  # type: Optional[List[int]]
        self.MATCHED_DETECTIONS = MATCHED_DETECTIONS  # type: int
        self.ROTATION = ROTATION  # type: Optional[List[float]]
        self.QUATERNION = QUATERNION  # type: Optional[List[float]]
        self.RESIDUAL_RMS_ARCSEC = RESIDUAL_RMS_ARCSEC  # type: float
        self.BORESIGHT_RA_DEG = BORESIGHT_RA_DEG  # type: float
        self.BORESIGHT_DEC_DEG = BORESIGHT_DEC_DEG  # type: float
        self.MATCHED_ROWS = MATCHED_ROWS  # type: Optional[List[int]]
        self.OCCULTATIONS = OCCULTATIONS  # type: Optional[List[SKROccultation.SKROccultationT]]
        self.EXCLUSIONS = EXCLUSIONS  # type: Optional[List[SKRExclusion.SKRExclusionT]]

    @classmethod
    def InitFromBuf(cls, buf, pos):
        tmpSkr = SKR()
        tmpSkr.Init(buf, pos)
        return cls.InitFromObj(tmpSkr)

    @classmethod
    def InitFromPackedBuf(cls, buf, pos=0):
        n = flatbuffers.encode.Get(flatbuffers.packer.uoffset, buf, pos)
        return cls.InitFromBuf(buf, pos+n)

    @classmethod
    def InitFromObj(cls, tmpSkr):
        x = SKRT()
        x._UnPack(tmpSkr)
        return x

    # SKRT
    def _UnPack(self, SKR):
        if SKR is None:
            return
        self.QUERY_ID = SKR.QUERY_ID()
        self.QUERY_KIND = SKR.QUERY_KIND()
        self.STATUS = SKR.STATUS()
        self.MESSAGE = SKR.MESSAGE()
        self.EPOCH_JD_TT = SKR.EPOCH_JD_TT()
        self.EPOCH_JD_TT_FRACTION = SKR.EPOCH_JD_TT_FRACTION()
        self.PLACE = SKR.PLACE()
        self.ROW_COUNT = SKR.ROW_COUNT()
        self.ROWS_ADDED = SKR.ROWS_ADDED()
        self.REJECTED_COUNT = SKR.REJECTED_COUNT()
        self.BAND_COUNT = SKR.BAND_COUNT()
        self.MATCHED_COUNT = SKR.MATCHED_COUNT()
        if not SKR.HITSIsNone():
            self.HITS = []
            for i in range(SKR.HITSLength()):
                if SKR.HITS(i) is None:
                    self.HITS.append(None)
                else:
                    sKRHit_ = SKRHit.SKRHitT.InitFromObj(SKR.HITS(i))
                    self.HITS.append(sKRHit_)
        if not SKR.BAND_IDSIsNone():
            self.BAND_IDS = []
            for i in range(SKR.BAND_IDSLength()):
                self.BAND_IDS.append(SKR.BAND_IDS(i))
        if not SKR.MAGNITUDESIsNone():
            if np is None:
                self.MAGNITUDES = []
                for i in range(SKR.MAGNITUDESLength()):
                    self.MAGNITUDES.append(SKR.MAGNITUDES(i))
            else:
                self.MAGNITUDES = SKR.MAGNITUDESAsNumpy()
        if not SKR.DERIVATIONSIsNone():
            if np is None:
                self.DERIVATIONS = []
                for i in range(SKR.DERIVATIONSLength()):
                    self.DERIVATIONS.append(SKR.DERIVATIONS(i))
            else:
                self.DERIVATIONS = SKR.DERIVATIONSAsNumpy()
        self.MATCHED_DETECTIONS = SKR.MATCHED_DETECTIONS()
        if not SKR.ROTATIONIsNone():
            if np is None:
                self.ROTATION = []
                for i in range(SKR.ROTATIONLength()):
                    self.ROTATION.append(SKR.ROTATION(i))
            else:
                self.ROTATION = SKR.ROTATIONAsNumpy()
        if not SKR.QUATERNIONIsNone():
            if np is None:
                self.QUATERNION = []
                for i in range(SKR.QUATERNIONLength()):
                    self.QUATERNION.append(SKR.QUATERNION(i))
            else:
                self.QUATERNION = SKR.QUATERNIONAsNumpy()
        self.RESIDUAL_RMS_ARCSEC = SKR.RESIDUAL_RMS_ARCSEC()
        self.BORESIGHT_RA_DEG = SKR.BORESIGHT_RA_DEG()
        self.BORESIGHT_DEC_DEG = SKR.BORESIGHT_DEC_DEG()
        if not SKR.MATCHED_ROWSIsNone():
            if np is None:
                self.MATCHED_ROWS = []
                for i in range(SKR.MATCHED_ROWSLength()):
                    self.MATCHED_ROWS.append(SKR.MATCHED_ROWS(i))
            else:
                self.MATCHED_ROWS = SKR.MATCHED_ROWSAsNumpy()
        if not SKR.OCCULTATIONSIsNone():
            self.OCCULTATIONS = []
            for i in range(SKR.OCCULTATIONSLength()):
                if SKR.OCCULTATIONS(i) is None:
                    self.OCCULTATIONS.append(None)
                else:
                    sKROccultation_ = SKROccultation.SKROccultationT.InitFromObj(SKR.OCCULTATIONS(i))
                    self.OCCULTATIONS.append(sKROccultation_)
        if not SKR.EXCLUSIONSIsNone():
            self.EXCLUSIONS = []
            for i in range(SKR.EXCLUSIONSLength()):
                if SKR.EXCLUSIONS(i) is None:
                    self.EXCLUSIONS.append(None)
                else:
                    sKRExclusion_ = SKRExclusion.SKRExclusionT.InitFromObj(SKR.EXCLUSIONS(i))
                    self.EXCLUSIONS.append(sKRExclusion_)

    # SKRT
    def Pack(self, builder):
        if self.QUERY_ID is not None:
            QUERY_ID = builder.CreateString(self.QUERY_ID)
        if self.MESSAGE is not None:
            MESSAGE = builder.CreateString(self.MESSAGE)
        if self.HITS is not None:
            SKRStartHITSVector(builder, len(self.HITS))
            for i in reversed(range(len(self.HITS))):
                self.HITS[i].Pack(builder)
            HITS = builder.EndVector()
        if self.BAND_IDS is not None:
            BAND_IDSlist = []
            for i in range(len(self.BAND_IDS)):
                BAND_IDSlist.append(builder.CreateString(self.BAND_IDS[i]))
            SKRStartBAND_IDSVector(builder, len(self.BAND_IDS))
            for i in reversed(range(len(self.BAND_IDS))):
                builder.PrependUOffsetTRelative(BAND_IDSlist[i])
            BAND_IDS = builder.EndVector()
        if self.MAGNITUDES is not None:
            if np is not None and type(self.MAGNITUDES) is np.ndarray:
                MAGNITUDES = builder.CreateNumpyVector(self.MAGNITUDES)
            else:
                SKRStartMAGNITUDESVector(builder, len(self.MAGNITUDES))
                for i in reversed(range(len(self.MAGNITUDES))):
                    builder.PrependFloat32(self.MAGNITUDES[i])
                MAGNITUDES = builder.EndVector()
        if self.DERIVATIONS is not None:
            if np is not None and type(self.DERIVATIONS) is np.ndarray:
                DERIVATIONS = builder.CreateNumpyVector(self.DERIVATIONS)
            else:
                SKRStartDERIVATIONSVector(builder, len(self.DERIVATIONS))
                for i in reversed(range(len(self.DERIVATIONS))):
                    builder.PrependUint8(self.DERIVATIONS[i])
                DERIVATIONS = builder.EndVector()
        if self.ROTATION is not None:
            if np is not None and type(self.ROTATION) is np.ndarray:
                ROTATION = builder.CreateNumpyVector(self.ROTATION)
            else:
                SKRStartROTATIONVector(builder, len(self.ROTATION))
                for i in reversed(range(len(self.ROTATION))):
                    builder.PrependFloat64(self.ROTATION[i])
                ROTATION = builder.EndVector()
        if self.QUATERNION is not None:
            if np is not None and type(self.QUATERNION) is np.ndarray:
                QUATERNION = builder.CreateNumpyVector(self.QUATERNION)
            else:
                SKRStartQUATERNIONVector(builder, len(self.QUATERNION))
                for i in reversed(range(len(self.QUATERNION))):
                    builder.PrependFloat64(self.QUATERNION[i])
                QUATERNION = builder.EndVector()
        if self.MATCHED_ROWS is not None:
            if np is not None and type(self.MATCHED_ROWS) is np.ndarray:
                MATCHED_ROWS = builder.CreateNumpyVector(self.MATCHED_ROWS)
            else:
                SKRStartMATCHED_ROWSVector(builder, len(self.MATCHED_ROWS))
                for i in reversed(range(len(self.MATCHED_ROWS))):
                    builder.PrependUint32(self.MATCHED_ROWS[i])
                MATCHED_ROWS = builder.EndVector()
        if self.OCCULTATIONS is not None:
            SKRStartOCCULTATIONSVector(builder, len(self.OCCULTATIONS))
            for i in reversed(range(len(self.OCCULTATIONS))):
                self.OCCULTATIONS[i].Pack(builder)
            OCCULTATIONS = builder.EndVector()
        if self.EXCLUSIONS is not None:
            SKRStartEXCLUSIONSVector(builder, len(self.EXCLUSIONS))
            for i in reversed(range(len(self.EXCLUSIONS))):
                self.EXCLUSIONS[i].Pack(builder)
            EXCLUSIONS = builder.EndVector()
        SKRStart(builder)
        if self.QUERY_ID is not None:
            SKRAddQUERY_ID(builder, QUERY_ID)
        SKRAddQUERY_KIND(builder, self.QUERY_KIND)
        SKRAddSTATUS(builder, self.STATUS)
        if self.MESSAGE is not None:
            SKRAddMESSAGE(builder, MESSAGE)
        SKRAddEPOCH_JD_TT(builder, self.EPOCH_JD_TT)
        SKRAddEPOCH_JD_TT_FRACTION(builder, self.EPOCH_JD_TT_FRACTION)
        SKRAddPLACE(builder, self.PLACE)
        SKRAddROW_COUNT(builder, self.ROW_COUNT)
        SKRAddROWS_ADDED(builder, self.ROWS_ADDED)
        SKRAddREJECTED_COUNT(builder, self.REJECTED_COUNT)
        SKRAddBAND_COUNT(builder, self.BAND_COUNT)
        SKRAddMATCHED_COUNT(builder, self.MATCHED_COUNT)
        if self.HITS is not None:
            SKRAddHITS(builder, HITS)
        if self.BAND_IDS is not None:
            SKRAddBAND_IDS(builder, BAND_IDS)
        if self.MAGNITUDES is not None:
            SKRAddMAGNITUDES(builder, MAGNITUDES)
        if self.DERIVATIONS is not None:
            SKRAddDERIVATIONS(builder, DERIVATIONS)
        SKRAddMATCHED_DETECTIONS(builder, self.MATCHED_DETECTIONS)
        if self.ROTATION is not None:
            SKRAddROTATION(builder, ROTATION)
        if self.QUATERNION is not None:
            SKRAddQUATERNION(builder, QUATERNION)
        SKRAddRESIDUAL_RMS_ARCSEC(builder, self.RESIDUAL_RMS_ARCSEC)
        SKRAddBORESIGHT_RA_DEG(builder, self.BORESIGHT_RA_DEG)
        SKRAddBORESIGHT_DEC_DEG(builder, self.BORESIGHT_DEC_DEG)
        if self.MATCHED_ROWS is not None:
            SKRAddMATCHED_ROWS(builder, MATCHED_ROWS)
        if self.OCCULTATIONS is not None:
            SKRAddOCCULTATIONS(builder, OCCULTATIONS)
        if self.EXCLUSIONS is not None:
            SKRAddEXCLUSIONS(builder, EXCLUSIONS)
        SKR = SKREnd(builder)
        return SKR
